,'2026-09-06 02:12:50','2026-09-06 02:12:50'),(109,8,77,9,5,3.000,NULL,NULL,17,'2026-09-06 02:12:50','2026-09-06 02:12:50'),(110,8,15,9,5,0.500,NULL,'freshly ground',18,'2026-09-06 02:12:50','2026-09-06 02:12:50'),(111,8,78,9,NULL,4.000,NULL,'white',19,'2026-09-06 02:12:50','2026-09-06 02:12:50'),(112,8,79,10,NULL,0.250,NULL,'small, very finely shredded',20,'2026-09-06 02:12:50','2026-09-06 02:12:50'),(113,8,80,10,NULL,2.000,NULL,'sliced into half moons',21,'2026-09-06 02:12:50','2026-09-06 02:12:50'),(114,8,81,10,NULL,4.000,6.000,'thinly sliced (optional)',22,'2026-09-06 02:12:50','2026-09-06 02:12:50');
