LOCK TABLES `recipes` WRITE;
/*!40000 ALTER TABLE `recipes` DISABLE KEYS */;
INSERT INTO `recipes` (`id`, `slug`, `title`, `description`, `tips`, `chef_id`, `cuisine_id`, `prep_time_band_id`, `cook_time_band_id`, `servings_min`, `servings_max`, `image_path`, `source_url`, `created_at`, `updated_at`) VALUES (1,'spaghetti-bolognese-with-mushrooms-and-sun-dried-tomatoes','Spaghetti bolognese with mushrooms and sun-dried tomatoes','Branch out from the classic with this different spag bol that adds marinated mushrooms and sun-dried tomatoes. Any leftovers will taste even better the next day.','You can make a veggie version of this recipe by substituting soya mince or Quorn for the meat, adding it to the sauce halfway through cooking. Or simply add lots of diced vegetables to the onions, such as courgettes, carrots, peppers and aubergines.',1,NULL,3,6,8,8,'images/recipes/spaghetti-bolognese.jpg','https://www.bbc.co.uk/food/recipes/spaghettibolognese_67868','2026-09-06 02:12:50','2026-09-06 02:12:50'),(2,'vegan-pancakes','Vegan pancakes','Try this vegan fluffy American pancake recipe for a perfect start to the day. Serve these pancakes with fresh berries, maple syrup or chocolate sauce for a really luxurious start to the day.','Whipped coconut cream is good with these too, but it must be well chilled before whipping. You can keep the pancakes warm in a low oven while you make the full batch.',2,1,3,4,2,2,'images/recipes/vegan-pancakes.jpg','https://www.bbc.co.uk/food/recipes/vegan_american_pancakes_76094','2026-09-06 02:12:50','2026-09-06 02:12:50'),(3,'healthy-pizza','Healthy pizza','No yeast required for this easy, healthy pizza, topped with colourful vegetables that\'s ready in 30 minutes. This is a great recipe if you want to feed the kids in a hurry.','You can use any cheese you like for this pizza - it\'s also a great way to use up a mix of odds and ends from the fridge. Make two pizzas instead of one large pizza if you like. Any leftover passata can be used for pasta sauces, stews or curries.',2,NULL,3,4,2,2,'images/recipes/healthy-pizza.jpg','https://www.bbc.co.uk/food/recipes/healthy_pizza_55143','2026-09-06 02:12:50','2026-09-06 02:12:50'),(4,'easy-lamb-biryani','Easy lamb biryani','This lamb biryani is a real centrepiece dish, but it\'s actually easy as anything to make. Serve garnished with pomegranate seeds to make it look really special.','Kashmiri red chilli powder is quite mild with a slightly smoky flavour that really adds to the dish.',3,2,8,6,6,8,'images/recipes/easy-lamb-biryani.jpg','https://www.bbc.co.uk/food/recipes/easy_lamb_biryani_46729','2026-09-06 02:12:50','2026-09-06 02:12:50'),(5,'couscous-salad','Couscous salad','A nutritious and satisfying vegan couscous salad packed with colour, flavour and texture, from dried cranberries, pistachios and pine nuts.','Couscous salads are great to make ahead for easy entertaining or weekday lunches. It will keep well for a few days in the fridge.',4,3,3,2,6,6,'images/recipes/couscous-salad.jpg','https://www.bbc.co.uk/food/recipes/dried_fruits_and_nuts_18053','2026-09-06 02:12:50','2026-09-06 02:12:50'),(6,'plum-clafoutis','Plum clafoutis','Halved plums are covered in a light batter and then baked in the oven to make this traditional French dessert. British plums are at their best in September, so make the most of them then and try this simple pud.',NULL,5,4,3,5,4,6,'images/recipes/plum-clafoutis.jpg','https://www.bbc.co.uk/food/recipes/plumclafoutis_11536','2026-09-06 02:12:50','2026-09-06 02:12:50'),(7,'mango-pie','Mango pie','This mouthwatering mango dessert is an Indian take on a traditional Thanksgiving pie. For this recipe, you will need two 23cm metal pie tins.','This recipe makes two pies, so halve the ingredients if you\'re not feeding a crowd.',6,NULL,5,5,16,16,'images/recipes/mango-pie.jpg','https://www.bbc.co.uk/food/recipes/mango_pie_18053','2026-09-06 02:12:50','2026-09-06 02:12:50'),(8,'mushroom-doner','Mushroom doner','A meat-free mushroom \'doner\' kebab packed with two types of sauces, pickles and veg. A mighty delicious vegetarian dish.',NULL,7,5,3,4,4,4,'images/recipes/mushroom-doner.jpg','https://www.bbc.co.uk/food/recipes/mushroom_doner_22676','2026-09-06 02:12:50','2026-09-06 02:12:50');
